// ---------------------------------------------------------------------------
// Minimal inline models (insertions only — no business-logic validation needed)
// ---------------------------------------------------------------------------

const makeModel = (name, collection) =>
  mongoose.models[name] ??
  mongoose.model(name, new mongoose.Schema({}, { strict: false, collection }));

const User        = makeModel('User',        'users');
const Property    = makeModel('Property',    'properties');
const Booking     = makeModel('Booking',     'bookings');
const Payment     = makeModel('Payment',     'payments');
const Promocode   = makeModel('Promocode',   'promocodes');
const Notification= makeModel('Notification','notifications');
const ChatMessage = makeModel('ChatMessage', 'chatmessages');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const upsertAll = async (Model, docs) => {
  if (!docs.length) return;
  const ops = docs.map((doc) => ({
    updateOne: {
      filter: { _id: doc._id },
      update:  { $set: doc },
      upsert:  true,
    },
  }));
  await Model.bulkWrite(ops, { ordered: false });
};

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

const MONGODB_URI = process.env.MONGODB_URI;

if (!MONGODB_URI) {
  console.error('❌  Missing environment variable: MONGODB_URI');
  process.exit(1);
}

const seedForce = String(process.env.SEED_FORCE ?? '').toLowerCase() === 'true';

const run = async () => {
  await mongoose.connect(MONGODB_URI);
  console.log('✅  Connected to MongoDB');

  try {
    // Skip if data already present and SEED_FORCE is not set
    if (!seedForce) {
      const existingUsers = await User.countDocuments({
        _id: { $in: users.map((u) => u._id) },
      });
      if (existingUsers > 0) {
        console.log('⏭️   Seed skipped: data already present. Set SEED_FORCE=true to override.');
        return;
      }
    }

    await Promise.all([
      upsertAll(User,         users),
      upsertAll(Property,     properties),
      upsertAll(Booking,      bookings),
      upsertAll(Payment,      payments),
      upsertAll(Promocode,    promocodes),
      upsertAll(Notification, notifications),
      upsertAll(ChatMessage,  chatMessages),
    ]);

    console.log('🌱  Seed complete:');
    console.log(`    users        → ${users.length}`);
    console.log(`    properties   → ${properties.length}`);
    console.log(`    bookings     → ${bookings.length}`);
    console.log(`    payments     → ${payments.length}`);
    console.log(`    promocodes   → ${promocodes.length}`);
    console.log(`    notifications→ ${notifications.length}`);
    console.log(`    chatMessages → ${chatMessages.length}`);
  } catch (err) {
    console.error('❌  Seed failed:', err);
    process.exitCode = 1;
  } finally {
    await mongoose.disconnect();
  }
};

run();